// Generated by AXIS — the OpenCode policy enforcement point. Do not hand-edit;
// change it through the catalog/generators and `axis sync`.
import { spawnSync } from "node:child_process";

export const AxisPolicy = async ({ directory }) => ({
  "tool.execute.before": async (input, output) => {
    const args = output?.args ?? {};
    const toolInput = {};
    if (args.command) toolInput.command = args.command;
    if (args.filePath) toolInput.file_path = args.filePath;
    else if (args.path) toolInput.file_path = args.path;
    // Both write shapes reach the secret scan: the write tool's whole-file
    // `content` and the edit tool's replacement `newString`, which the adapter
    // reads as `new_string`. Dropping either one lets a credential through on
    // OpenCode while the same edit is blocked everywhere else.
    if (args.content) toolInput.content = args.content;
    if (args.newString) toolInput.new_string = args.newString;

    const payload = JSON.stringify({
      cwd: directory,
      // OpenCode's own session id keys the per-session state (the rate-limit
      // count). Without it every session in the repo shares one bucket that
      // never resets, turning a per-session cap into a lifetime one.
      session_id: input?.sessionID,
      tool_name: input?.tool,
      tool_input: toolInput,
    });

    const res = spawnSync("axis", ["guard", "--target", "opencode", "--mode", "unattended"], {
      input: payload,
      encoding: "utf8",
    });
    // No axis on this machine: a named hard block with the bootstrap steps. An
    // onboarded repo cannot be used with OpenCode until axis is installed.
    if (res.error) {
      throw new Error("axis is not installed on this machine, and this repo has a policy hook that needs it.\n  run: gcloud auth login\n  then: curl -fsSL https://axis.egen.dev/install.sh | sh");
    }
    // A non-zero exit is a refusal (a version pin this machine cannot honor, or a
    // launcher fault); stderr is not echoed, since it is not this plugin's to relay.
    if (res.status !== 0) {
      throw new Error("blocked by axis policy (axis exited " + res.status + ")");
    }
    let decision;
    try {
      decision = JSON.parse(res.stdout).hookSpecificOutput.permissionDecision;
    } catch {
      throw new Error("blocked by axis policy (unreadable verdict)");
    }
    if (decision === "deny" || decision === "ask") {
      throw new Error("blocked by axis policy (" + decision + ")");
    }
  },
});
